  const profileDefaults={displayName:'',email:'',signature:'',phone:'',tone:'Friendly',nameFormat:'Display name'};
  function saveAuthSession(session){authSession=session;try{if(session)localStorage.setItem(AUTH_KEY,JSON.stringify(session));else localStorage.removeItem(AUTH_KEY)}catch{}updateAuthButton()}
  function updateAuthButton(){const button=$('#authButton');if(button)button.textContent=authSession?.user?.email?'Account':'Sign in'}
  async function supabaseAuth(path,body,accessToken){const rawUrl=String(supabaseConfig.url||''),url=rawUrl.endsWith('/')?rawUrl.slice(0,-1):rawUrl;const key=supabaseConfig.publishableKey;if(!/^https:\/\//.test(url)||!key||key.includes('YOUR_'))throw new Error('Add your Supabase project URL and publishable key in supabase-config.js first.');const headers={'Content-Type':'application/json','apikey':key};if(accessToken)headers.Authorization=`Bearer ${accessToken}`;const response=await fetch(`${url}/auth/v1${path}`,{method:'POST',headers,body:JSON.stringify(body)});const result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.msg||result.message||result.error_description||result.error||'Supabase authentication failed.');return result}
  function authModal(mode='signin'){modal('Local-only workspace','No account or cloud service is connected. To move your data and preferences to another device, export a backup in Settings and restore it there.','<div class="form-actions"><button class="btn primary" id="authDone">Done</button></div>');$('#authDone').onclick=closeModal;return;if(authSession?.user){modal('Supabase account','You are signed in. Production data is still stored locally until cloud sync is added.',`<p class="record-card">${esc(authSession.user.email||'Signed in')}</p><div class="form-actions"><button class="btn ghost" id="authDone">Close</button><button class="btn danger" id="authSignOut">Sign out</button></div>`);$('#authDone').onclick=closeModal;$('#authSignOut').onclick=async()=>{try{if(authSession.access_token)await supabaseAuth('/logout',{},authSession.access_token)}catch{}saveAuthSession(null);closeModal();showToast('Signed out of your Supabase account.');};return}
    const create=mode==='signup';modal(create?'Create account':'Sign in','Use an email and password for your Supabase account. This does not yet sync production data.',`<div class="form-actions" style="justify-content:flex-start;margin:0 0 14px"><button type="button" class="btn ${create?'ghost':''} small" id="authModeSignIn">Sign in</button><button type="button" class="btn ${create?'':'ghost'} small" id="authModeSignUp">Create account</button></div><form id="authForm" class="form-grid"><div class="field full"><label for="authEmail">Email address</label><input id="authEmail" name="email" type="email" autocomplete="email" required></div><div class="field full"><label for="authPassword">Password</label><input id="authPassword" name="password" type="password" autocomplete="${create?'new-password':'current-password'}" minlength="6" required></div><div class="field full form-actions"><button type="button" class="btn ghost" id="authCancel">Cancel</button><button class="btn primary" type="submit">${create?'Create account':'Sign in'}</button></div></form><p class="panel-sub" id="authMessage" aria-live="polite"></p>`);$('#authModeSignIn').onclick=()=>authModal('signin');$('#authModeSignUp').onclick=()=>authModal('signup');$('#authCancel').onclick=closeModal;$('#authForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,submit=form.querySelector('[type="submit"]'),message=$('#authMessage'),values=new FormData(form),email=String(values.get('email')||'').trim(),password=String(values.get('password')||'');submit.disabled=true;message.textContent=create?'Creating your account…':'Signing in…';try{const result=await supabaseAuth(create?'/signup':'/token?grant_type=password',{email,password});if(result.access_token){saveAuthSession(result);closeModal();showToast(create?'Account created and signed in.':'Signed in to Supabase.')}else if(create){message.textContent='Account created. Check your email for a confirmation link, then sign in.';submit.disabled=false;showToast('Check your email to confirm your account.')}else throw new Error('Supabase did not return a session. Check your project Auth settings.')}catch(error){message.textContent=error.message;submit.disabled=false}}}
  async function restoreAuthSession(){if(!authSession?.refresh_token||!supabaseConfig.url||!supabaseConfig.publishableKey||supabaseConfig.publishableKey.includes('YOUR_'))return;try{const refreshed=await supabaseAuth('/token?grant_type=refresh_token',{refresh_token:authSession.refresh_token});saveAuthSession(refreshed)}catch{saveAuthSession(null)}}
  function load(){try{const saved=JSON.parse(localStorage.getItem(KEY));if(!saved)return emptyProduction('');const blank=emptyProduction('');const state={...blank,...saved,setup:{...blank.setup,...saved.setup},profile:{...profileDefaults,...saved.profile}};if(saved.isSample){for(const key of ['notes','tasks','events','contacts','drafts','templates'])state[key]=(state[key]||[]).filter(item=>!item.sample);state.directors=(state.directors||[]).filter(item=>item.id!=='d1');state.activity=(state.activity||[]).filter(item=>!['Sample activity','Sample data'].includes(item.when));state.production='';state.theatre='';state.details='';state.setup.production=false;state.setup.directors=state.directors.length>0;state.isSample=false}return state}catch{return emptyProduction('')}}
  let data=load(), page='dashboard', selectedNote=null, selectedDate='2027-01-04', monthCursor=new Date(2027,0,1), toastTimer;
