    if(name==='prev-month'){monthCursor=new Date(monthCursor.getFullYear(),monthCursor.getMonth()-1,1);selectedDate=`${monthCursor.getFullYear()}-${String(monthCursor.getMonth()+1).padStart(2,'0')}-01`;render();return}if(name==='next-month'){monthCursor=new Date(monthCursor.getFullYear(),monthCursor.getMonth()+1,1);selectedDate=`${monthCursor.getFullYear()}-${String(monthCursor.getMonth()+1).padStart(2,'0')}-01`;render();return}if(name==='this-month'){const now=new Date();monthCursor=new Date(now.getFullYear(),now.getMonth(),1);selectedDate=todayISO();render();return}if(name==='save-note'){const n=data.notes.find(x=>x.id===id);if(!n)return;for(const [key,sel] of Object.entries({scene:'#detailScene',page:'#detailPage',category:'#detailCategory',status:'#detailStatus',priority:'#detailPriority',date:'#detailDate',text:'#detailText'}))n[key]=$(sel).value;log(`Note corrected: ${n.title}`);save();render();showToast('Note changes saved locally.');return}if(name==='note-task'){const n=data.notes.find(x=>x.id===id);if(!n)return;data.tasks.unshift({id:uid(),title:n.title,description:n.text,due:'',status:'To Do',priority:n.priority,noteId:n.id,scene:n.scene});log(`Task created from note: ${n.title}`);save();render();showToast('Task created and linked to the note.');return}
